WITH car AS (SELECT REPLACE(a.id_imovel,'-','') id_car_norm,a.id_imovel,a.id_municipio,a.area,SAFE_DIVIDE(ST_AREA(a.geometria),10000) area_geometria_ha,a.status,a.condicao,a.tipo FROM `basedosdados.br_sfb_sicar.area_imovel` a WHERE a.id_imovel='BA-2929701-3438EBE3EC1C4160B13A7DC99112E048' AND a.data_extracao>=DATE '2026-06-02' AND a.data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY a.id_imovel ORDER BY a.data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm,cpf,cnpj_basico FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),mut AS (SELECT DISTINCT id_referencia_bacen,cpf,cnpj FROM `basedosdados.br_bcb_sicor.recurso_publico_mutuario` WHERE ano_emissao BETWEEN 2013 AND 2026),x AS (SELECT p.ano_emissao,p.id_referencia_bacen,p.numero_ordem,p.cpf,p.cnpj_basico,op.data_emissao,op.valor_parcela_credito,op.area_financiada,op.id_empreendimento,op.id_programa,op.cnpj_basico_instituicao_financeira,e.produto,e.finalidade,i.nome instituicao,i.segmento,COALESCE(NULLIF(mut.cpf,''),NULLIF(mut.cnpj,'')) doc_mutuario FROM p JOIN car USING(id_car_norm) JOIN `basedosdados.br_bcb_sicor.operacao` op USING(ano_emissao,id_referencia_bacen,numero_ordem) LEFT JOIN mut USING(id_referencia_bacen) LEFT JOIN `basedosdados.br_bcb_sicor.empreendimento` e USING(id_empreendimento) LEFT JOIN `basedosdados.br_bcb_sicor.instituicao_financeira` i ON i.cnpj_basico=op.cnpj_basico_instituicao_financeira),g AS (SELECT ano_emissao,id_referencia_bacen,numero_ordem,MIN(data_emissao) data_emissao,MAX(valor_parcela_credito) valor_parcela_credito,MAX(area_financiada) area_financiada,ANY_VALUE(produto) produto,ANY_VALUE(finalidade) finalidade,ANY_VALUE(instituicao) instituicao,ANY_VALUE(segmento) segmento,COUNT(DISTINCT COALESCE(NULLIF(cpf,''),NULLIF(cnpj_basico,''))) proprietarios_distintos,COUNT(DISTINCT doc_mutuario) mutuarios_distintos FROM x GROUP BY 1,2,3) SELECT * FROM g ORDER BY data_emissao,id_referencia_bacen,numero_ordem